INSERT OR IGNORE INTO "user" ("id", "categorie", "statut_adhesion", "role_plateforme", "prenom", "nom", "email", "pays", "ville", "biographie", "photo_url", "specialite", "secteurs_expertise", "niveau_etudes", "organisation", "linkedin_url", "site_web_url", "langues", "annuaire_visible", "ouvert_contact", "newsletter_brevo", "notif_opportunites", "notif_evenements", "created_at", "updated_at") VALUES ('37db4fd1-8890-4526-b606-61144926143a', 'professionnel', 'en_attente_paiement', 'membre', 'Remyaga', 'KOUMANTEGA', 'remyagaguyk@gmail.com', 'Togo', 'Lomé', NULL, NULL, 'Productions végétales', NULL, NULL, NULL, NULL, NULL, NULL, 1, 1, 1, 1, 1, '2026-06-27T22:18:37.636927+00:00', '2026-06-27T22:18:37.636927+00:00');

