INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('777ce98e-b06f-420e-97d6-961306f91152', 'L''Agriculture Hors Sol', 'Auteur inconnu', 'article', 'public', 'publie', 'Présentation de COCOSOL, une entreprise ivoirienne spécialisée dans la promotion et le développement de l''agriculture hors sol (hydroponie) pour les cultures maraîchères, en utilisant des terreaux à base de fibre de coco.', 'Agriculture hors sol / Hydroponie', NULL, NULL, 'fr', NULL, '1782476059309-8_cocosol_culture_hors_sol.pdf', 5277282, 1, NULL, NULL, '2026-06-26T12:14:25.555659+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('61c1e9e7-4016-488d-a8b0-656602fb5ea9', 'Guide des pratiques agroécologiques - Département de Mbour, Sénégal', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide capitalise les pratiques agroécologiques testées et validées avec 110 exploitations familiales dans le cadre du projet REFSA (Renforcement des Exploitations agricoles Familiales et Sécurité Alimentaire) mené entre 2013 et 2015. Il aborde principalement les techniques de maraîchage visant à réduire la vulnérabilité des exploitations face aux contraintes environnementales et économiques, notamment le recours excessif aux produits chimiques. Réalisé en français et en wolof par Ag', 'Agroécologie', NULL, NULL, 'fr', NULL, '1782476075993-977-guide-agroecologie-agrisud-fr.pdf', 5369197, 0, NULL, NULL, '2026-06-26T12:14:41.15617+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('481320f0-7157-4982-8f55-a64f87c281e1', 'Les bases théoriques et pratiques de l''agriculture conventionnelle', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document est un cours de Master 1 en Productions Végétales (M1.P.V) dispensé à SNV El Oued en 2021, portant sur l''agriculture durable. Le premier chapitre détaille les itinéraires techniques des principales cultures de plein champ, en se concentrant sur le travail du sol. Il distingue le travail profond (labour, sous-solage, décompactage) du travail superficiel (déchaumage), en expliquant les objectifs, les outils et les profondeurs associés à chaque opération.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476088799-Agriculture_durable_Chapitre_et_2.pdf', 1168601, 0, NULL, NULL, '2026-06-26T12:14:50.860558+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('6f045b88-9a9a-4b2b-bd19-b34cb99fff81', 'Agriculture sous abri : Structure, conditions requises et usage des serres sous différents climats', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document, numéro 23 de la série Agrodok publiée par la Fondation Agromisa, est un guide technique sur l''agriculture sous abri. Il présente les structures de serres, les conditions requises pour leur mise en place et leur utilisation dans différents contextes climatiques, en s''adressant aux pratiquants de l''agriculture durable à petite échelle.', 'Agriculture sous abri / Serres', NULL, NULL, 'fr', NULL, '1782476099211-Agriculture_sous_abri.pdf', 1439457, 0, NULL, NULL, '2026-06-26T12:15:02.0187+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('d44b3686-dd2b-4a83-a94a-dc3c21f8d53c', 'Analyse de la filière maraichage au Burkina Faso', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document présente une analyse complète de la filière maraîchère au Burkina Faso, réalisée par des cadres du Ministère de l''Agriculture avec l''appui de la FAO. Il examine le contexte national et international, l''organisation du marché, les circuits de distribution et les principales spéculations maraîchères. L''étude propose une analyse fonctionnelle détaillée des acteurs et des flux de la filière pour l''élaboration de politiques agricoles.', 'Filière agricole', NULL, NULL, 'fr', NULL, '1782476102534-07061bc9d3c38a134e6336d645b46be2ff724e7a__2_.pdf', 2429511, 0, NULL, NULL, '2026-06-26T12:15:07.118539+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('6bb2c644-33fa-434d-8fd8-323e87e64656', 'Agriculture urbaine : la culture des légumes en ville', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce guide pratique de la série Agrodok, publié par Agromisa, fournit des conseils accessibles sur les techniques de culture maraîchère en milieu urbain. Il s''adresse aux petits producteurs et jardiniers souhaitant produire des légumes en ville de manière durable. Le document fait partie d''une collection plus large couvrant divers aspects de l''agriculture à petite échelle en zones tropicales.', 'Agriculture urbaine', NULL, NULL, 'fr', NULL, '1782476116516-Agriculture_urbaine.pdf', 1381908, 0, NULL, NULL, '2026-06-26T12:15:18.914666+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('73e911eb-a116-47e5-b5db-c206f116f488', 'Itinéraire technique du blé dur bio', 'Auteur inconnu', 'article', 'public', 'publie', 'Cette fiche technique présente les bonnes pratiques culturales pour la production de blé dur en agriculture biologique, en particulier dans le cadre du projet BIODUR-PACA en région méditerranéenne. Elle détaille le choix des précédents culturaux (privilégiant les légumineuses pluriannuelles comme le sainfoin ou la luzerne), la préparation du sol, les spécificités du blé dur par rapport aux autres céréales, ainsi que les itinéraires techniques de semis (dates, profondeur, densité) et le', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476121095-1._Fiche_technique_ble_dur_bio_BIODUR_PACA_2023.pdf', 1388029, 0, NULL, NULL, '2026-06-26T12:15:24.615653+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('99a0a5a3-d4f1-4ab5-8dac-363d0b864f77', 'Agricultures singulières', 'Auteur inconnu', 'article', 'public', 'publie', 'L''ouvrage examine la diversité des agricultures singulières à travers le monde, analysant leurs spécificités socio-économiques et environnementales, et leur rôle dans le développement rural.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476123907-agricultures-singulieres.pdf', 13518486, 0, NULL, NULL, '2026-06-26T12:15:43.856588+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('f33d1d2a-8d8f-42dc-b5b6-29406579d6d0', 'La culture du soja et d''autres légumineuses', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document est le numéro 10 de la série Agrodok, une collection de guides techniques sur l''agriculture durable à petite échelle. Il traite de la culture du soja et d''autres légumineuses, couvrant les aspects pratiques de leur production. Il s''adresse aux petits producteurs et aux praticiens agricoles des zones tropicales.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476154779-Agrodok_10_-_La_ulture_du_Soja_et_autres_legumineuses.pdf', 2723529, 0, NULL, NULL, '2026-06-26T12:16:00.632197+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('04bdee2b-3c2a-4c6e-9b4c-96073a44c19e', '1001 questions de jardinage (Pouliot, Paul).pdf', 'Auteur inconnu', 'article', 'public', 'publie', 'Description générée automatiquement.', 'Non classé', NULL, NULL, 'fr', NULL, '1782476128228-1001_questions_de_jardinage__Pouliot__Paul_.pdf', 22369065, 0, NULL, NULL, '2026-06-26T12:16:00.972457+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('49572747-76e5-4cbc-a52e-99b4b0e8d704', 'La culture des tomates : production, transformation et commercialisation', 'Auteur inconnu', 'article', 'public', 'publie', 'Le document est une fiche technique de la série Agrodok (n°17) consacrée à la culture des tomates en zones tropicales à petite échelle. Il couvre l''ensemble de la filière, de la production à la transformation et la commercialisation. Rédigé par plusieurs auteurs et publié par Agromisa et le CTA, il vise à fournir des conseils pratiques et accessibles aux petits producteurs.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476169357-1297_PDF_1.pdf', 1146774, 0, NULL, NULL, '2026-06-26T12:16:11.134879+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('bdddf98b-02f0-492b-b5a5-bdeda006cb50', 'Du compost enrichi pour des rendements plus élevés', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce guide pratique, publié par le CTA (Centre technique de coopération agricole et rurale), explique comment produire un compost enrichi de bonne qualité à partir des déchets agricoles et ménagers en Afrique orientale. Il détaille les principes du compostage, les avantages du compost enrichi pour la fertilité des sols et l''augmentation des rendements, en proposant une alternative abordable aux engrais chimiques coûteux.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476177142-1471_full_text_smaller.pdf', 509012, 0, NULL, NULL, '2026-06-26T12:16:18.215362+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('f4458f6c-ac21-40db-9fca-45600c0ca2f2', 'Transformation et conditionnement de l''huile d''olive biologique', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document présente un projet de création d''une unité de trituration et de conditionnement d''huile d''olive biologique en Tunisie. Il dresse un état des lieux du secteur oléicole biologique aux niveaux national et international, détaille les aspects techniques, réglementaires et financiers du projet, et analyse la rentabilité prévisionnelle de l''activité.', 'Filière oléicole biologique', NULL, NULL, 'fr', NULL, '1782476185597-15.pdf', 1705631, 0, NULL, NULL, '2026-06-26T12:16:27.741862+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('7df09ad3-306a-45a8-921f-7517205759f5', 'Fiche technique culture d’arachide', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique, produite dans le cadre du projet d''appui aux organisations professionnelles agricoles des Districts de Belo sur Tsiribihina et Morondava (région Menabe), présente les bonnes pratiques pour améliorer la culture de l''arachide. Elle aborde les systèmes de culture à adopter (rotation, association culturale, jachère améliorée) ainsi que l''itinéraire technique détaillé, incluant le choix et le traitement des semences, les dates de semis et la préparation du sol pour le', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476200741-151._fiche_tech_arachide.pdf', 1037456, 2, NULL, NULL, '2026-06-26T12:16:42.773484+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('9f32d2c2-636c-4a25-9466-cbf13c204406', 'Agrodok 8 - La fabrication et l''utilisation du compost', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document est le huitième numéro de la série Agrodok, une collection de guides techniques sur l''agriculture durable à petite échelle. Rédigé par plusieurs experts et publié par la Fondation Agromisa, il expose de manière pratique les méthodes de fabrication et d''utilisation du compost en contexte tropical. Il s''adresse aux petits producteurs et aux agents de vulgarisation souhaitant améliorer la fertilité des sols de façon accessible et peu coûteuse.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476201119-Agrodok-08-La-fabrication-et-lutilisation-du-compost.pdf', 1605997, 0, NULL, NULL, '2026-06-26T12:16:44.095187+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('65316875-ea10-4f80-ada1-5675717dc598', 'FICHE TECHNIQUE: PIMENT', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique présente de manière détaillée la culture du piment, de la préparation de la pépinière à la mise en place et l''entretien de la culture en plein champ. Elle fournit des instructions sur le choix et la préparation du sol, les densités de plantation, la fertilisation, ainsi que les traitements phytosanitaires recommandés (fongicides, insecticides, désherbants) tout au long du cycle cultural. Le document inclut également les coordonnées de l''entreprise Phytotop, spécia', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476211119-1650452131_phytotop_pratique_agricole02.pdf', 88109, 0, NULL, NULL, '2026-06-26T12:16:52.63548+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('dc6beec3-2cd6-497e-8936-f961d20af28e', 'L''agroécologie : principes, méthodes & processus clés à dynamiser en systèmes de grandes cultures pour l''agriculture de demain', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document retrace les origines historiques de l''agroécologie, depuis la critique de la révolution verte dans les pays du Nord jusqu''aux mouvements paysans en Amérique du Sud. Il explore les principes fondamentaux de l''agroécologie, les leviers et méthodes applicables aux systèmes de grandes cultures, et souligne l''importance de repenser les démarches de conception et de coordination pour une agriculture durable.', 'Agroécologie', NULL, NULL, 'fr', NULL, '1782476213239-Agroecologie.pdf', 3693111, 0, NULL, NULL, '2026-06-26T12:16:59.344799+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('78325893-fb6f-4c2c-b62a-6c8fe77d47ef', 'FICHE TECHNIQUE : TOMATE', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Fiche technique produite par Le Top de la protection phytosanitaire, détaillant la culture de la tomate de la pépinière à la récolte. Elle couvre la préparation du sol, la gestion de la pépinière, la plantation et la protection phytosanitaire contre les maladies et ravageurs.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476219124-1650452477_phytotop_pratique_agricole02.pdf', 69496, 0, NULL, NULL, '2026-06-26T12:16:59.78921+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('21858d84-224a-4150-a6d7-80e741ba5cfe', 'Guide de formation sur l''arboriculture fruitière', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce document est un guide de formation élaboré pour les agents d''encadrement des exploitants agricoles en zone sahélienne au Niger, dans le cadre du projet EDOS. Il couvre les techniques de l''arboriculture fruitière depuis l''installation d''une pépinière jusqu''à l''entretien des arbres adultes, en passant par le greffage et la plantation.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476226224-17FGuide-de-formation-sur-larboriculture-fruitiere.pdf', 498745, 0, NULL, NULL, '2026-06-26T12:17:07.55767+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('391eba3a-62c8-4ff1-ab91-ee02bdd22a1d', 'Cours d''Agronomie I : Sol et Eau', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document est un support de cours d''agronomie consacré à l''étude du sol et de l''eau. Il définit le sol comme la couche externe de la croûte terrestre résultant de l''interaction entre lithosphère, atmosphère, hydrosphère et biosphère, et détaille ses éléments constitutifs (fractions minérale, organique, fluide et gazeuse). Le cours aborde également la classification granulométrique des constituants minéraux (sables, limons, argiles) et la texture du sol.', 'Sciences du sol / Agronomie', NULL, NULL, 'fr', NULL, '1782476226894-agronomie_1_cours_et_TD_univ_Blida_.pdf', 5463760, 0, NULL, NULL, '2026-06-26T12:17:12.354988+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('2a0c8cd5-703f-445a-b4fb-0e1df41c3014', 'Support de formation sur l''arboriculture fruitière', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document est un support de formation destiné aux exploitants agricoles de la zone sahélienne au Niger, dans le cadre du projet EDOS (Etude de Développement des Oasis Sahéliennes). Il couvre les techniques de production de plants en pépinière, le greffage (manguier, agrumes), la plantation et l''entretien des arbres fruitiers. L''objectif est d''aProducteurs à maîtriser les techniques culturales pour développer les cultures fruitières en zone sahélienne.', 'Arboriculture fruitière', NULL, NULL, 'fr', NULL, '1782476235728-18FSupport-de-formation-sur-larboriculture-fruitiere__2_.pdf', 620853, 0, NULL, NULL, '2026-06-26T12:17:17.659196+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('cd2c9cbe-e667-4932-aad9-14c7b81169df', 'Agronomie I', 'Auteur inconnu', 'article', 'public', 'publie', 'Document de deuxième année en sciences agronomiques présentant les définitions fondamentales du sol selon trois perspectives : pédologique, agronomique et écologique. Il aborde les processus d''altération physique et chimique ainsi que le rôle du sol comme support de végétation et milieu triphasique à l''interface de la biosphère et de la lithosphère.', 'Agronomie', NULL, NULL, 'fr', NULL, '1782476238352-Agronomie_I___1_.pdf', 1712016, 0, NULL, NULL, '2026-06-26T12:17:21.487864+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ea8d5f32-b91b-4407-b07b-9c74b4be3592', 'Pourquoi être agronome ?', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document de Damien Joubert, ancien élève du Lycée du Parc, explore les motivations et les enjeux du métier d''agronome. Il propose une définition de l''agronomie et de l''agro-alimentaire, et présente les perspectives d''une profession liée à l''étude des relations entre plantes, sol, climat et techniques de culture.', 'Agronomie', NULL, NULL, 'fr', NULL, '1782476249942-agronomie.pdf', 1110450, 0, NULL, NULL, '2026-06-26T12:17:32.154282+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('37dad6ee-3081-4b97-81e5-89c8884b531f', 'LA CULTURE DES AGRUMES EN POLYNESIE FRANÇAISE', 'Auteur inconnu', 'article', 'public', 'publie', 'Fiche technique éditée par la Direction de l''agriculture de Polynésie française, rééditée en 2018, présentant l''itinéraire de culture des agrumes. Elle détaille le choix des terrains et des parcelles, notamment les antécédents culturaux, les qualités des sols, le drainage et l''approvisionnement en eau, ainsi que les aménagements nécessaires avant plantation.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782476260343-agrume_ft_itineraire_culture_maladies_ravageurs_polynesieFrancaise.pdf', 3285442, 0, NULL, NULL, '2026-06-26T12:17:46.183847+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('804130c5-a035-4855-9ec0-537cbc6568e3', 'Maladies et ravageurs de la tomate', 'Auteur inconnu', 'article', 'public', 'publie', 'Fiche technique réalisée par la FREDEC de la région Centre présentant les principales maladies et ravageurs affectant la tomate, avec leurs symptômes, conditions favorables, modes de dissémination et méthodes de lutte. Elle couvre notamment le mildiou, l''alternariose, la maladie des racines liégeuses, les attaques de Phytophthora et les viroses, en insistant sur les bonnes pratiques culturales sous abri.', 'Phytopathologie', NULL, NULL, 'fr', NULL, '1782476274551-alteragri_51_2002_p12-13.pdf', 383608, 0, NULL, NULL, '2026-06-26T12:17:55.705439+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('dd6425e7-208b-47ae-8966-7e9f03013b44', 'Technologie clé de compétitivité dans l''activité AMIDONS ET GLUTENS DE BLE', 'Auteur inconnu', 'article', 'public', 'publie', 'Ce document détaille les procédés industriels de séparation et de traitement du blé en amidon, farine et gluten. Il décrit les différentes étapes de transformation incluant la mouture, le tamisage, la centrifugation, la désamidation et le séchage, menant à la production d''amidon A, d''amidon B, de fécule et de gluten vital.', 'Techniques agroalimentaires', NULL, NULL, 'fr', NULL, '1782476282079-amidon_de_ble_gluten_glutenines_fecule.pdf', 51010, 1, NULL, NULL, '2026-06-26T12:18:03.003454+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('1dc1fb15-644a-4113-ab5b-211f731946c3', 'ISAA-MF 2004 - Produits du Maïs', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique détaille les procédés industriels de transformation du maïs. Il présente les différents produits et co-produits obtenus, notamment l''amidon, le gluten, l''huile, la farine, le sorbitol et d''autres dérivés, ainsi que les étapes de fabrication comme le trempage, le broyage, la centrifugation et diverses opérations de purification et de transformation chimique.', 'Transformation agroalimentaire - Maïs', NULL, NULL, 'fr', NULL, '1782479050760-amidon_de_mais_gluten_dextrine_semoule_dextrose_isoglucose_sorbitol.pdf', 54168, 0, NULL, NULL, '2026-06-26T13:04:12.013033+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('0603a42c-75a8-48a5-ba62-b85b00947771', 'Analyse nutritionnelle de la papaye transgénique, premier fruit GM commercialisé', 'Auteur inconnu', 'article', 'public', 'publie', 'Cette étude, menée par l''Université d''Hawaï et l''USDA, a comparé la composition nutritionnelle de la papaye transgénique (cultivar Rainbow), modifiée pour résister au virus PRSV, à celle de papayes conventionnelles à différents stades de mûrissement. Les résultats montrent aucune différence significative pour les 36 nutriments analysés, à l''exception de variations mineures en vitamine A, calcium et papaïne, restant dans les marges de variation statistique. Les auteurs concluent à l''équ', 'Sécurité alimentaire et OGM', NULL, NULL, 'fr', NULL, '1782479063365-Analyse_nutritionnelle_papaye_GM_2012.pdf', 122357, 0, NULL, NULL, '2026-06-26T13:04:23.904413+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('79fb71d4-f64b-410a-ad5f-2aa0dcd0c3a9', 'TECHNOLOGIE DE PRODUCTION DE L''ANANAS', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente la technologie de production de l''ananas, couvrant ses exigences climatiques et pédologiques, la conduite de la culture (sélection du matériel végal, plantation, protection phytosanitaire, fumure), ainsi que les techniques de traitement d''induction florale et de récolte. Il décrit également les principales variétés cultivées, notamment le Cayenne Lisse, et les objectifs d''amélioration variétale.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479073307-ANANAS.pdf', 2400496, 0, NULL, NULL, '2026-06-26T13:04:42.32407+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('40f85f22-0b42-4575-95d1-a0c11ac9849f', 'Guide pratique sur l''utilisation des produits d''extraits naturels et des engrais liquides biologiques', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce document, édité par la Chambre Nationale d''Agriculture du Burkina Faso, présente les possibilités d''utilisation de biopesticides et d''extraits naturels pour la protection des cultures. Il détaille les modes d''action, les avantages et les recettes de préparation de divers produits à base de plantes locales (neem, piment, tabac, etc.) ainsi que la fabrication et l''utilisation d''engrais liquides biologiques.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479090482-angrais_bio__2_.pdf', 2417261, 0, NULL, NULL, '2026-06-26T13:04:53.482393+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('787df327-840e-4619-877d-0e8c2621fe4c', 'TECHNOLOGIE DE PRODUCTION DE L''ARACHIDE (Arachis hypogaea)', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document, édité par l''Institut de Formation en Agriculture et Technologies Innovantes, présente la technologie de production de l''arachide au Cameroun. Il détaille les variétés cultivées (groupes Spanish, Valencia et Virginia), les exigences pédo-climatiques de la culture, ainsi que les bonnes pratiques de conduite, de récolte et de rendement. Il s''agit d''un outil de formation destiné aux professionnels et techniciens agricoles.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479103408-ARACHIDE.pdf', 1279028, 0, NULL, NULL, '2026-06-26T13:05:05.12578+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('8d46ec27-4d83-4655-8aa5-3be00e7f2288', 'Artemisia annua : fiche technique de culture (Madagascar-Cameroun)', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique présente les méthodes de culture de l''Artemisia annua, une plante riche en artémisinine utilisée dans la lutte contre le paludisme. Elle détaille les conditions pédoclimatiques, le calendrier cultural, la préparation du sol, les techniques de semis et de plantation, ainsi que l''entretien et l''arrosage de cette espèce. Le document s''appuie sur des expériences menées à Madagascar et au Cameroun.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479112601-ARTEMISIA_ANNUA.pdf', 185372, 0, NULL, NULL, '2026-06-26T13:05:13.177138+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('44819326-18cb-4fff-ba71-e908da2e294e', 'Atlas Biologie Animale 2. Les grandes fonctions', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ouvrage pédagogique de biologie animale destiné aux étudiants de Licence, Prépas et CAPES. Il présente les grandes fonctions physiologiques des animaux, avec une approche visuelle et structurée typique des atlas scientifiques.', 'Biologie animale', NULL, NULL, 'fr', NULL, '1782479119115-Atlas_de_biologie_animale_-_Tome_2._Les_grandes_fonctions.pdf', 40808662, 0, NULL, NULL, '2026-06-26T13:06:07.902949+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('b402baec-805c-42df-93b1-4fdab34eeb7d', 'La culture du papayer au Sénégal', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique présente les méthodes et techniques de culture du papayer au Sénégal, dans le cadre du projet régional pour le développement des cultures maraîchères en Afrique de l''Ouest. Il a été réalisé par le Centre pour le Développement de l''Horticulture (CDH) de Cambérène-Dakar, en collaboration avec l''ISRA et la FAO, et constitue une référence sur l''arboriculture fruitière au Sénégal.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479181167-az813f.pdf', 530848, 0, NULL, NULL, '2026-06-26T13:06:21.947177+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('6e156215-3eb6-4727-a919-23015b679813', 'TECHNOLOGIE DE PRODUCTION DES REJETS DE BANANIER PLANTAIN PAR LA TECHNIQUE PIF (Plants Issus de Fragments de Tiges)', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique présente la méthode PIF (Plants Issus de Fragments de Tiges) pour la production de rejets de bananier plantain, en détaillant le matériel nécessaire, la construction du germoir, l''ombrière, le choix du rejet et l''entretien des plants. Il aborde également la technologie de culture du bananier plantain dans son ensemble, couvrant les exigences agronomiques, la préparation du terrain, la plantation, l''entretien des cultures et la récolte.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479193484-BANANIER_PLANTAIN__2_.pdf', 2170588, 0, NULL, NULL, '2026-06-26T13:06:36.682085+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('c4d9b3d3-771d-4b61-ab00-be31f2435234', 'OTitre du document ( caractères latins)', 'Auteur inconnu', 'article', 'public', 'publie', 'Description générée automatiquement.', 'Ancien', NULL, NULL, 'fr', NULL, '1782479201995-Betterave_sucriere.pdf', 1887099, 0, NULL, NULL, '2026-06-26T13:06:43.889348+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('71415313-3805-4190-b611-f7a222372716', 'Technologie clé de compétitivité dans l''activité BEURRES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente le procédé de fabrication des beurre, détaillant les étapes de transformation du lait et de la crème fraîche en beurres frais, allégés et congelés. Il couvre les opérations de pasteurisation, cristallisation, maturation, barratage, malaxage et conditionnement. Il inclut également les ingrédients et intermédiaires utilisés tels que le babeurre, les levains, les protéines de lait et les arômes.', 'Technologie agroalimentaire', NULL, NULL, 'fr', NULL, '1782479211874-Beurres.pdf', 40510, 0, NULL, NULL, '2026-06-26T13:06:52.475674+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('88be2b10-eb03-49ef-acad-7750f814767f', 'Bioécologie des bioagresseurs (Partie 1) – Chapitre 1 : Introduction à l''agro-écosystème', 'Auteur inconnu', 'memoire', 'public', 'publie', 'Ce document est un support de cours universitaire destiné aux étudiants en L3 Protection des végétaux. Il présente les fondements de l''agro-écosystème, en distinguant écosystème naturel et agro-écosystème, et détaille les composants des chaînes trophiques (producteurs, consommateurs, décomposeurs) ainsi que les différents types de pyramides écologiques. L''objectif final est de fournir les connaissances écologiques nécessaires à la protection des cultures et à la réduction du recours au', 'Agroécologie', NULL, NULL, 'fr', NULL, '1782479220468-BIOECOLOGIE_L3PTV_partie1.pdf', 2536679, 0, NULL, NULL, '2026-06-26T13:07:03.604857+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('e3b50fbe-28e9-465f-84c8-51f711c1ceb6', 'Chapitre IV : Morphologie des végétaux supérieurs et adaptation', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce chapitre de biologie végétale présente la morphologie des plantes supérieures, en définissant cette discipline et en la distinguant de l''anatomie. Il détaille ensuite la racine, organe souterrain de fixation et d''absorption, en décrivant ses trois types principaux : pivotant, fasciculé et adventif.', 'Biologie végétale', NULL, NULL, 'fr', NULL, '1782479229489-Biologie_v_g_tale_-_chapitre_4.pdf', 3491326, 0, NULL, NULL, '2026-06-26T13:07:13.978705+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('31d3f866-aeb4-4c3a-a96d-0cc6a2fd20bf', 'Culture du tournesol en Bio', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Fiche technique destinée aux agriculteurs bio de la région PACA, détaillant itinéraire cultural, choix varietal, semis, fertilisation et désherbage du tournesol. Elle insiste sur la place en rotation, les variétés résistantes aux maladies fongiques et les interventions mécaniques de désherbage.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479242309-bio_de_paca_tournesol.pdf', 1297409, 0, NULL, NULL, '2026-06-26T13:07:24.915461+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('731c3222-5087-4416-8c21-8f8d98df3c3b', 'Technologie clé de compétitivité dans l''activité Bisucs - Pâtisseries - Pizzas', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Document technique décrivant les procédés de fabrication pour les biscuits, pâtisseries et pizzas. Il détaille les ingrédients, les étapes de préparation de la pâte, et les opérations de façonnage, cuisson et conditionnement.', 'Technologies alimentaires', NULL, NULL, 'fr', NULL, '1782479252081-biscuits_patisseries_pizzas.pdf', 39203, 0, NULL, NULL, '2026-06-26T13:07:32.902623+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('4204abb4-be32-4985-81ba-eb3466d7a92a', 'Technologie clé de compétitivité dans l''activité Blé précuit à cuisiner', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document décrit le procédé industriel de fabrication du blé précuit destiné à la cuisson, depuis la réception du blé dur jusqu''au conditionnement du produit fini. Il détaille les étapes clés telles que le tamisage, le pré-cuisson à 100°C, le séchage en tambour rotatif, le décorticage par meules abrasives et la porisation par choc thermique à 250°C. Il met en évidence les facteurs de compétitivité de cette technologie de transformation céréalière.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479261750-ble_precuit_a_cuisiner.pdf', 15123, 0, NULL, NULL, '2026-06-26T13:07:42.609859+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('d18cb24c-6204-4176-8331-c60751ea847b', 'Maïs - Bonnes pratiques agricoles', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide pratique présente les étapes clés de la culture du maïs, du choix de la parcelle à la récolte, en passant par l''achat des intrants, le semis, le désherbage et la fertilisation. Il est basé sur l''expérience de producteurs qui partagent leurs techniques pour obtenir de bons rendements et un maïs de qualité.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479272561-Bonnes_pratiques_agricoles_pour_le_ma_s.pdf', 350126, 0, NULL, NULL, '2026-06-26T13:07:53.358488+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('a0205acd-b8ff-464f-816b-cfe7d9e3fdad', 'Bonnes pratiques de CES/DRS : contribution à l''adaptation au changement climatique et à la résilience des producteurs – Les expériences de quelques projets au Sahel', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce document présente un inventaire des bonnes pratiques de conservation des eaux et des sols (CES) et de défense et restauration des sols (DRS) mises en œuvre dans les projets de coopération allemande au Sahel. Il détaille les principales techniques d''aménagement (demi-lunes, tranchées Nardi, banquettes, cordons pierreux, zaï, etc.), leur fonctionnement, les démarches participatives adoptées pour leur mise en œuvre, ainsi que les possibilités de réplication, en s''appuyant sur l''analyse', 'Changement climatique', NULL, NULL, 'fr', NULL, '1782479288090-Bonnes__pratiques-CES-DRS-GIZ.pdf', 4448205, 0, NULL, NULL, '2026-06-26T13:08:18.191881+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('695d4372-bbce-4c92-a18b-4c3ad1235e5e', 'La fertilisation organique des cultures : Les bases', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Brochure produite par la Fédération d''agriculture biologique du Québec (FABQ) en 2005, visant à outiller les producteurs, conseillers et étudiants en agriculture sur la gestion des matières organiques en fertilisation. Elle vulgarise les connaissances techniques disponibles pour améliorer l''efficacité des cultures au départ de végétation, accroître les rendements et réduire la pollution liée à une fertilisation excessive. Le document a été réalisé par Jacques Petit et Pierre Jobin avec', 'Agriculture biologique', NULL, NULL, 'fr', NULL, '1782479312011-Brochure_fertilisation15nov.pdf', 3042607, 0, NULL, NULL, '2026-06-26T13:08:37.184149+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ecd66b32-3d93-45dc-922c-fce55ed787c1', 'BRSA, Boissons gazeuses, Eau de table : Technologie clé de compétitivité', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique décrit les procédés de fabrication des boissons gazeuses, de l''eau de table et de la limonade, en détaillant les étapes clés telles que la déminéralisation, la pasteurisation, la gazéification et l''embouteillage. Il met en évidence les matières premières utilisées (eau, sucre, concentrés, CO₂) et les technologies de compétitivité propres à l''industrie des boissons rafraîchissantes sans alcool (BRSA).', 'Industrie agroalimentaire', NULL, NULL, 'fr', NULL, '1782479325233-BRSA_boissons_gazeuses_eau.pdf', 30040, 0, NULL, NULL, '2026-06-26T13:08:45.734765+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('a4e22183-e6d0-41f5-a162-6ff247de1113', 'GUIDE DAR AL MOUKAWIL - BUSINESS PLAN', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce document est un guide pratique destiné aux entrepreneurs, expliquant de manière structurée comment réaliser un business plan. Il aborde les différentes étapes essentielles : la définition du business plan, la description des produits et services, le positionnement de l''entreprise, la stratégie d''attaque de marché, l''organisation de l''équipe dirigeante, l''évaluation des risques et les prévisions financières. Un exemple concret de business plan est également fourni pour illustrer la t', 'Entrepreneuriat', NULL, NULL, 'fr', NULL, '1782479333773-bussiness_plan.pdf', 799337, 0, NULL, NULL, '2026-06-26T13:08:54.64741+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('f6eeceec-7ec7-4d12-8df0-08ee8a6255e9', 'La fertilité des sols : L''importance de la matière organique', 'Auteur inconnu', 'rapport', 'public', 'publie', 'Ce document est un rapport technique décrivant le rôle central de la matière organique dans la fertilité des sols. Il détaille les propriétés et processus d''humification, les organismes du sol (vers de terre, champignons, micro-organismes) et propose une analyse comparative de différentes sources de matière organique sur 10 ans, ainsi qu''une présentation de la méthode Bourguignon de fertilisation. Il s''inscrit dans une réflexion agronomique approfondie sur la préservation et l''améliora', 'Pédologie et fertilité des sols', NULL, NULL, 'fr', NULL, '1782479342221-ca67-amendements_organiques.pdf', 2071002, 0, NULL, NULL, '2026-06-26T13:09:04.705031+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('1829bdb9-0e89-4d63-98b5-36a198dd4c6d', 'Technologie clé de compétitivité dans l''activité CAFES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique décrit les différentes étapes de transformation des cerises de caféier en produits finis (café vert nature, café vert lavé, café moulu, café lyophilisé, extrait liquide de café). Il compare les méthodes sèche et humide de traitement post-récolte, couvrant des opérations telles que le dépulpage, la fermentation, le séchage, la torréfaction et le conditionnement.', 'Techniques de transformation du café', NULL, NULL, 'fr', NULL, '1782479352050-cafe_moulu_et_lyophilise.pdf', 17077, 0, NULL, NULL, '2026-06-26T13:09:12.638003+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('b4fa6b09-7840-4c66-8007-d8dea9f1c952', 'Technologie de la culture du caféier', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document de formation dresse un panorama complet de la culture du caféier, depuis les généralités botaniques (arabica et robusta) jusqu''aux pratiques culturales détaillées (matériel végétal, pépinière, plantation, ent fertilisation, lutte phytosanitaire), en passant par les exigences pédoclimatiques, les utilisations du café et les techniques de récolte et post-récolte.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479357988-CAFEIER.pdf', 1276852, 0, NULL, NULL, '2026-06-26T13:09:19.375699+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('edf7f2b8-9ce6-4d81-8850-f543565d423c', 'TECHNOLOGIE DE CULTURE DE LA CANNE A SUCRE', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document, édité par l''Institut de Formation en Agriculture et Technologies Innovantes, présente la technologie de culture de la canne à sucre. Il couvre les généralités sur la plante (espèces, histoire, produits dérivés), ses exigences culturales, la conduite de la culture, ainsi que la récolte et les opérations post-récolte. Il s''agit d''un support de formation détaillé destiné aux professionnels et étudiants du secteur agricole.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479367927-CANNE_A_SUCRE.pdf', 1240864, 0, NULL, NULL, '2026-06-26T13:09:29.438211+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('3dcc26b4-d1fe-4c65-8557-0c293ac7f5b5', 'Fiche technique Tomate', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document est une fiche technique consacrée à la culture de la tomate en Afrique. Il détaille les généralités sur l''espèce, les types de variétés (à port indéterminé ou déterminé), les exigences climatiques et pédologiques, ainsi que les techniques de semis et de production de plants.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479374912-CEFCNSTECPV_.02.pdf', 143598, 0, NULL, NULL, '2026-06-26T13:09:35.490415+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('57b4c788-3ea8-4b3a-b094-bfb96eb83db7', 'chicoree.pdf', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Document technique sur la torréfaction et la transformation industrielle de la chicorée, incluant un schéma de procédé de fabrication.', 'Transformation agroalimentaire', NULL, NULL, 'fr', NULL, '1782479382286-chicoree.pdf', 29111, 0, NULL, NULL, '2026-06-26T13:09:42.90574+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('a43cf0a7-0262-4a06-b59a-0db3ef74929c', 'Concentrés de fruits et légumes : Réception / Stockage', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les étapes clés de la production de concentrés de fruits et légumes, couvrant la réception, le stockage, le lavage, le broyage, la pasteurisation, l''atomisation et le conditionnement des produits sous forme de poudres, flocons et pulpes. Il détaille les processus technologiques utilisés pour transformer les matières premières en produits concentrés destinés à l''industrie agroalimentaire.', 'Technologie agroalimentaire', NULL, NULL, 'fr', NULL, '1782479391780-concentres_flocons_poudres_fruits_legumes.pdf', 37170, 0, NULL, NULL, '2026-06-26T13:09:52.181547+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('10243158-842a-4405-97e3-7ce9e51f0b87', 'Confiseries en dragées : Technologie clé de compétitivité dans l''activité', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document constitue un guide technique détaillé sur les procédés de fabrication de confiseries en dragées (amandes, nougatines, billes, etc.). Il décrit les étapes successives de fabrication telles que le grossissement, l''enrobage, le gommage, le candissage, le polissage et le conditionnement. Il met en avant les ingrédients, équipements et techniques nécessaires pour maîtriser cette production-confiserie.', 'Agroalimentaire / Confiserie', NULL, NULL, 'fr', NULL, '1782479402015-confiseries_en_dragees_sucre_chocolat_liqueur_amande.pdf', 51717, 0, NULL, NULL, '2026-06-26T13:10:02.357471+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('68d6df10-281f-4130-b3e1-18486a227992', 'conserves surgeles de poisson.pdf', 'Auteur inconnu', 'article', 'public', 'publie', 'Description générée automatiquement.', 'Non classé', NULL, NULL, 'fr', NULL, '1782479406533-conserves_surgeles_de_poisson.pdf', 31873, 0, NULL, NULL, '2026-06-26T13:10:06.771251+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('47bca097-c695-4b3f-8261-2d1e1d8c5b82', 'Technologie clé de compétitivité dans l''activité CREMES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document décrit un procédé industriel de transformation laitière, probablement la fabrication de crème et de sous-produits (crème fraîche, crème en poudre, crème concentrée). Il détaille les étapes technologiques principales : réception du lait cru, écrémage, bactofugation, thermisation, homogénéisation, fermentation, pasteurisation et conditionnement, avec l''utilisation de levains et d''enzymes.', 'Technologies agroalaitières', NULL, NULL, 'fr', NULL, '1782479413700-cremes_laitieres.pdf', 27845, 0, NULL, NULL, '2026-06-26T13:10:14.255064+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('1cf85403-6adc-45c3-8b2a-b56043f29dba', 'Technologie clé de compétitivité dans l''activité EAU DE VIE ET SOUS-PRODUITS DE VIN', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente un schéma technologique détaillé du processus de production des eaux de vie et de valorisation des sous-produits de la vinification. Il couvre les étapes de réception du vin et des lies, la distillation (alambic, colonne), la concentration sous vide, le vieillissement en fûts, ainsi que la production de sous-produirs tels que le tartrate de chaux, les engrais organiques liquides, le terreau et les anthocyanes.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479426017-eaux_de_vie_anthocyanes_huiles_essentielles_engrais_organiques.pdf', 41578, 0, NULL, NULL, '2026-06-26T13:10:26.41123+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('e839e549-7c4e-43ff-8cf6-ef4ef3bd19d9', 'Technologie clé de compétitivité dans l''activité : Extraits d''épices et d''aromates, antioxydants naturels', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés d''extraction et de transformation des épices et aromates bruts en divers produits (essences, huiles essentielles, oléorésines, antioxydants naturels, etc.). Il détaille les étapes technologiques telles que le broyage, la distillation, la filtration, l''émulsification et la micronisation, illustrées par un schéma de flux de production.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479438580-epices_aromates_antioxydants_naturels_oleoresines.pdf', 50390, 0, NULL, NULL, '2026-06-26T13:10:38.958353+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('a7c1262d-739d-41c3-a12e-a02ebc99986f', 'Fécule – Albumine : Technologie clé de compétitivité dans l’activité', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente le processus industriel de production de fécule et d''albumine à partir de pommes de terre, détaillant les étapes de réception, lavage, broyage, centrifugation, filtration, séchage, et ensachage. Il met en avant les technologies clés permettant d''améliorer la compétitivité dans ce secteur, notamment la récupération d''albumine (protéine coagulée) à partir des eaux de process.', 'Techniques agroalimentaires', NULL, NULL, 'fr', NULL, '1782479448898-Fecule_de_pomme_de_terre_pulpe_d_albumine.pdf', 28082, 0, NULL, NULL, '2026-06-26T13:10:49.462354+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('314a1854-b1ba-4a85-9ad1-bb7d02f44ab0', 'Fiche technique sur la culture du piment', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique vise à aider les producteurs et les agents de vulgarisation à respecter l''itinéraire technique de la culture du piment au Bénin, afin d''améliorer les rendements. Elle aborde les contraintes majeures de la production, telles que la gestion des ravageurs, l''utilisation de variétés dégénérées et la non-maîtrise de l''eau. Le document présente également les concepts de base liés à la plante et aux variétés cultivées.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479455963-FICHE-TECHNIQUE-5-ITINERAIRE-TECHNIQUE-DU-PIMENT-PEPPER-TECHNICAL-ITINERARY.pdf', 2731744, 0, NULL, NULL, '2026-06-26T13:11:01.038713+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('d78b83b1-cb9a-44c3-9602-87d28b0924b5', 'Fiche 5 - Culture Artemisia annua', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique, publiée par la Maison de l''Artemisia en 2020, détaille les bonnes pratiques culturales pour la production d''Artemisia annua. Elle couvre la préparation de la parcelle, les techniques agroécologiques (compost, paillage, conservation des sols), ainsi que les étapes de transplantation avec les recommandations de fumure organique. Des conseils spécifiques sont donnés sur les amendements autorisés en agriculture biologique et l''adaptation des pratiques aux conditions ', 'Culture de plantes médicinales', NULL, NULL, 'fr', NULL, '1782479469099-Fiche_5_Culture_annua_2020.pdf', 176499, 0, NULL, NULL, '2026-06-26T13:11:09.686682+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('9111cb10-5021-4612-aa83-8cd5484e02ad', 'Fiche technico-économique pour la culture de la tomate', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique, produite par la Chambre Régionale d''Agriculture d''Agadez, présente les éléments techniques et économiques pour la culture de la tomate dans la région d''Agadez. Elle détaille les pratiques culturales (choix du sol, semis, irrigation, protection phytosanitaire, récolte) ainsi qu''une analyse des coûts et de la rentabilité de cette culture maraîchère.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479497364-fiche_technico-economique_tomate_cra_agadez_mars2020.pdf', 304122, 0, NULL, NULL, '2026-06-26T13:11:38.320696+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ec1ebebb-2234-4de2-a267-6b97525d09f0', 'Technologie clé de compétitivité dans l''activité FROMAGES FONDUS', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document est une fiche technique détaillée illustrant les procédés de fabrication des fromages fondus, couvrant les différentes étapes (mélange, écroûtage, découpage, cuisson, homogénéisation) pour des fromages à pâte pressée cuite et à pâte dure, jusqu''au conditionnement et entreposage réfrigéré.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479509097-fromages_fondus.pdf', 42584, 0, NULL, NULL, '2026-06-26T13:11:49.932046+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('4a2d16e0-fe43-4e34-ad54-298f8fc12fd4', 'Technologie clé de compétitivité dans l''activité Fruits Transformés — Réception de fruits frais et procédés de transformation', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique présente les principales étapes des chaînes de transformation de fruits frais (cerises, mirabelles, abricots, poires, pêches, pommes) en produits dérivés tels que fruits confits, fruits au sirop, compotes, confitures et gelées. Il détaille les opérations unitaires comme le lavage, le dénoyautage, le pelage, la cuisson, le saumurage, la fermentation anaérobie, la pasteurisation et la mise en boîte, ainsi que les paramètres clés (températions, durages, additions de ', 'Techniques agroalimentaires', NULL, NULL, 'fr', NULL, '1782479537376-fruits_au_sirop_compotes_confitures_gelees_cerises_confites.pdf', 51766, 0, NULL, NULL, '2026-06-26T13:12:18.225215+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('5d8422b1-8085-4662-903a-8068b40ad739', 'Business plan type - Guide de structuration', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Modèle de business plan détaillant la structure type d''un plan d''affaires, section par section. Il fournit des instructions et des questions clés pour chaque partie : résumé, portrait d''entreprise, produits/services, marché, plan marketing, infrastructure, gestion financière et évaluation des risques. L''objectif est de guider la rédaction d''un business plan complet pour présenter une demande de financement, de partenariat ou tout autre objectif stratégique.', 'Gestion d''entreprise', NULL, NULL, 'fr', NULL, '1782479547531-FSE___Fiche_Business_plan.pdf', 102969, 0, NULL, NULL, '2026-06-26T13:12:28.15997+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('d5524a55-7e75-46e6-b24d-89b0e08c72f3', 'Le compostage facilité : guide sur le compostage domestique', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide, réalisé par Nova Envirocom sous la direction de Josée Duplessis, présente les principes et les techniques du compostage domestique. Il s''inscrit dans une démarche de sensibilisation à l''environnement et de promotion du développement durable. L''ouvrage vise à éduquer le grand public sur les pratiques accessibles de compostage à domicile.', 'Environnement', NULL, NULL, 'fr', NULL, '1782479556174-Guide_de_compostage_domestique.pdf', 3407839, 0, NULL, NULL, '2026-06-26T13:12:40.265797+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('4b8e6f69-1d1d-4a0c-b94e-d09405e34672', 'Guide d''élevage des volailles au Sénégal', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide technique, publié en 1997 par l''ISRA et le CIRAD, synthétise les connaissances destinées aux éleveurs, vétérinaires et techniciens pour l''aviculture au Sénégal. Il couvre la construction des bâtiments d''élevage, l''alimentation des volailles (besoins nutritionnels, matières premières locales, formulation des rations) et la conduite de l''élevage (choix des souches). Il constitue un outil de référence pratique pour le développement de l''aviculture tropicale.', 'Élevage avicole', NULL, NULL, 'fr', NULL, '1782479569606-Guide__levage_de_volaille_.pdf', 53453699, 0, NULL, NULL, '2026-06-26T13:13:44.916051+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('a77357a6-c32c-4dbc-bcfd-669a7afce209', 'Guide pratique sur le compostage : principes, méthodes et mise en œuvre', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce document est un guide complet sur le compostage, abordant les principes fondamentaux, les types de biodéchets compostables, les différentes méthodes et les facteurs influençant le processus de décomposition. Il détaille également les aspects réglementaires et normatifs, ainsi qu''un exemple concret de projet de compostage en tas, de l''implantation à l''analyse du produit fini, en passant par des conseils pour la sensibilisation du public.', 'Gestion des déchets et compostage', NULL, NULL, 'fr', NULL, '1782479644103-guide-compostage.pdf', 846048, 0, NULL, NULL, '2026-06-26T13:14:05.2173+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ac8c2549-d6e4-4d6a-8fde-d2a8aae8dde2', 'Guide d’élaboration d’un plan d’action de développement durable', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide, publié en octobre 2015 par le Ministère du Développement durable, de l''Environnement et de la Lutte contre les changements climatiques du Québec, accompagne les ministères et organismes dans la création de leur plan d’action de développement durable (PADD). Il détaille les étapes d''élaboration, depuis la détermination des objectifs jusqu''à la reddition de comptes, en passant par la définition des actions et des indicateurs, afin de contribuer à la Stratégie gouvernementale de', 'Développement durable', NULL, NULL, 'fr', NULL, '1782479657048-guide-elabo-plandd.pdf', 593039, 0, NULL, NULL, '2026-06-26T13:14:18.180134+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('82ef0421-33ea-4cdf-8492-a4879a0d6e30', 'Guide agriculture bio', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Fiche de la Fédération Régionale d''Agriculture Biologique de Nouvelle-Aquitaine présentant les fondamentaux de l''agriculture biologique, la réglementation européenne (règlement UE 2018/848) et française, les grands principes agronomiques, les règles d''étiquetage et le processus d''obtention du label AB.', 'Agriculture biologique', NULL, NULL, 'fr', NULL, '1782479687582-Guide-Produire-BIO-2024-2.pdf', 22911292, 0, NULL, NULL, '2026-06-26T13:16:08.409672+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('0ddd2901-fa60-4b66-ad49-84d8f4d05a80', 'Guide de rédaction de plan d''affaires', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide pratique fournit une méthodologie détaillée pour la rédaction d''un plan d''affaires, en couvrant toutes les étapes clés : présentation du projet, analyse du marché, plan marketing, opérations, ressources humaines et plan financier. Il s''adresse aux entrepreneurs et promoteurs de projets souhaitant structurer et formaliser leur stratégie d''entreprise. La première édition constitue un outil de référence pour élaborer un document complet et convaincant auprès des partenaires finan', 'Entrepreneuriat', NULL, NULL, 'fr', NULL, '1782479780183-GUIDE_REDAC_PLAN_FR_2019_WEB.pdf', 1166099, 0, NULL, NULL, '2026-06-26T13:16:21.600573+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('dd6d6fea-b160-4d00-9b25-1241b2aeaa5e', 'Technologie clé de compétitivité dans l''activité HUILES DE BEURRE', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente un procédé alternatif de production d''huile de beurre et de matière grasse laitière anhydre (MGLA) à partir de crème à 40% de matière grasse. Il détaille les étapes du processus, incluant la pasteurisation, la concentration par centrifugation, l''homogénéisation, le séchage sous vide et la fonte, ainsi que la valorisation des sous-produits comme le babeurre et le bêta-sérum.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479791858-huile_de_beurre_MGLA_babeurre_betaserum.pdf', 34917, 0, NULL, NULL, '2026-06-26T13:16:32.268508+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('f5af21ec-756b-4ea6-87a6-a38c6ac480f5', 'Technologie clé de compétitivité dans l''activité HUILES – MARGARINES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés industriels de transformation des graines oléagineuses en huiles et margarines, couvrant l''ensemble de la chaîne de production : réception des graines, extraction par solvant, raffinage (décoloration, désodorisation, neutralisation), ainsi que les étapes de formulation, cristallisation et conditionnement des produits finaux. Il détaille les flux de matières, les équipements utilisés et les paramètres de process (températions, pressions, vide) pour chaq', 'Technologie agroalimentaire – Corps gras', NULL, NULL, 'fr', NULL, '1782479800826-huile_margarine_tourteaux_furfural_cires_savon_mucilages.pdf', 34783, 0, NULL, NULL, '2026-06-26T13:16:41.358117+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('c74df308-cb07-4ac4-ae00-555dfa40e898', 'Technologie clé de compétitivité dans l''activité', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés industriels de fabrication de jus de fruits et de concentrés de fruits, couvrant les étapes de réception des fruits, d''extraction, de clarification, de pasteurisation et de concentration. Il détaille les technologies clés telles que la flash pasteurisation, la filtration sur diatomées et la déturbidisation, visant à garantir la compétitivité de cette activité.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479809292-jus_concentre_de_fruits.pdf', 39453, 0, NULL, NULL, '2026-06-26T13:16:49.634244+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('09696f1b-29be-4ea0-b21b-1112debee9cd', 'La culture de la tomate', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce document est un guide pratique présenté par AgroConseil détaillant l''ensemble des étapes de la culture de la tomate (Solanum lycopersicum L.), depuis le choix du terrain et des variétés jusqu''à la récolte, la conservation et la commercialisation. Il aborde des aspects tels que la préparation du sol, l''installation de l''irrigation, le repiquage, le tuteurage et l''entretien des cultures. Il s''adresse aux agriculteurs et horticulteurs souhaitant optimiser la production de tomates.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479817671-la_tomate.pdf', 1913157, 0, NULL, NULL, '2026-06-26T13:16:59.573405+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ee2d01b2-5d66-4c5b-b838-854c34a9fcf0', 'Technologie clé de compétitivité dans l''activité LAITS CONCENTRES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document décrit les procédés de fabrication des laits concentrés sucrés et non sucrés, depuis la réception du lait cru jusqu''au conditionnement et à la stérilisation. Il détaille les étapes technologiques incluant l''écrémage, la standardisation, l''évaporation, le mélange avec du sucre ou du lactose, ainsi que les traitements thermiques comme l''upérisation et la pasteurisation. Les diagrammes de flux illustrent les paramètres critiques de température et de concentration en matière gr', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479828006-laits_concentres.pdf', 29273, 0, NULL, NULL, '2026-06-26T13:17:08.461558+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('b177fa09-5c28-4cec-bf2f-e5bd8d131f9f', 'Les sept familles de l''agriculture durable', 'Auteur inconnu', 'article', 'public', 'publie', 'Cet article analyse et compare sept modèles d''agriculture durable (agriculture biologique, régénérative, de conservation, climato-intelligente, biodynamie, permaculture et agroécologie) en les distinguant de l''agriculture conventionnelle. Il examine leurs positionnements, objectifs et pratiques, en soulignant leurs différences philosophiques et méthodologiques. Les auteurs proposent une clarification de ces agricultures écologisées pour mieux les évaluer et les différencier.', 'Agriculture durable', NULL, NULL, 'fr', NULL, '1782479834894-Les_sept_familles_de_l_agriculture_durable.pdf', 3962451, 0, NULL, NULL, '2026-06-26T13:17:19.372848+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('4d74c56a-580e-4e2a-bf7d-30f240eb5729', 'Technologie clé de compétitivité dans l''activité Levure boulangère', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document décrit le processus industriel de production de levure boulangère fraîche et sèche active, en détaillant les matières premières utilisées (mélasse, azote, air stérile, engrais) ainsi que les étapes de fabrication telles que la fermentation, la centrifugation, la filtration, la déshydratation et le conditionnement. Il met en évidence les flux de matières et les opérations unitaires impliquées dans la chaîne de production.', 'Industrie agroalimentaire', NULL, NULL, 'fr', NULL, '1782479847259-levure_boulangere.pdf', 31116, 0, NULL, NULL, '2026-06-26T13:17:27.796663+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('db5f9576-7159-44bf-99f0-565b1cfab04d', 'Manager une entreprise agricole durable : Pour une démarche entrepreneuriale responsable, rémunératrice et résiliente', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce manuel pratique s''adresse aux agriculteurs entrepreneurs souhaitant intégrer les principes du développement durable dans la gestion de leur exploitation. Il présente les enjeux environnementaux, sociaux et économiques de l''agriculture du XXIe siècle et propose une démarche concrète de Responsabilité Sociétale de l''Entreprise Agricole (RSEA) pour atteindre la triple performance. L''auteur, fort de 15 ans d''expérience, offre des clés pour rendre l''entreprise agricole plus résiliente to', 'Gestion de l''entreprise agricole', NULL, NULL, 'fr', NULL, '1782479856283-Manager_une_entreprise_agricole.pdf', 757709, 0, NULL, NULL, '2026-06-26T13:17:37.033659+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('8f513555-680c-49dc-bb81-18870be99597', 'Technologie clé de compétitivité dans l''activité MAYONNAISE', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document technique traite du processus de fabrication de la mayonnaise, en détaillant les ingrédients (produits secs, huile, jaune d''œuf, vinaigre, eau, sel, sucre, épices), les étapes clés telles que le dosage, le mélange, l''émulsion (broyage à vide) et le conditionnement. Il met en avant les facteurs de compétitivité liés à cette technologie de production.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479867532-mayonnaise_emulsionnee.pdf', 26781, 0, NULL, NULL, '2026-06-26T13:17:47.847745+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ce1c204c-e479-48f9-8bea-49782544774b', 'Gestion de Projets', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les concepts fondamentaux de la gestion de projets, en définissant ce qu''est un projet selon la norme ISO 9000 et en expliquant les principes de la gestion de projet. Il aborde l''organisation, la planification et le suivi nécessaires pour mener à bien un projet en respectant les contraintes de délais, de coûts et de ressources.', 'Gestion de projets', NULL, NULL, 'fr', NULL, '1782479873690-module-gestion-de-projet.pdf', 448444, 1, NULL, NULL, '2026-06-26T13:17:54.471344+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('cec370bb-0626-42b4-bb8b-e1dbedfb66d7', 'Technologie clé de compétitivité dans l''activité PAINS – BISCOTTES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés de fabrication, les dosages et les étapes de production pour différents types de pains et biscuits, incluant les versions crues, surgelées, précuites et grillées. Il détaille les formulations à base de farine de blé et d''autres farines, ainsi que les paramètres de pétrissage, fermentation, surgélation, cuisson et distribution. Il s''agit d''un guide technique destiné aux professionnels de la boulangerie industrielle et artisanale.', 'Boulangerie industrielle', NULL, NULL, 'fr', NULL, '1782479882102-pain_biscottes.pdf', 44753, 0, NULL, NULL, '2026-06-26T13:18:02.455117+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('0f9c8a78-5db8-4c27-bc31-d1ed0e723908', 'Technologie de production de pastèque (Cucumis melo)', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Fiche technique de l''Institut de Formation en Agriculture et Technologies Innovantes présentant la culture de la pastèque au Cameroun. Le document détaille les exigences de la culture, la préparation du sol, le choix des variétés, les semis, la fertilisation, les traitements phytosanitaires ainsi que la récolte et les rendements. Il met en valeur la valeur nutritive et médicinale du fruit, de plus en plus intégré dans les habitudes alimentaires camerounaises.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479889419-PASTEQUE.pdf', 1429911, 0, NULL, NULL, '2026-06-26T13:18:11.196042+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('7307fb65-0f46-4738-824c-aaee5ff76163', 'Technologie clé de compétitivité dans l''activité PÂTES ALIMENTAIRES (ISAA-MF 2004)', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les différentes étapes du procédé de fabrication des pâtes alimentaires, de la réception des matières premières (semoule de blé dur, œufs) jusqu''au conditionnement, en passant par le dosage, le mélange, l''extrusion, le séchage à très haute température et les opérations de finition. Il met en avant les technologies clés influençant la compétitivité dans ce secteur industriel.', 'Industrie agroalimentaire', NULL, NULL, 'fr', NULL, '1782479921188-pates_alimentaires_nouilles_spaghettis_macaronis_couscous.pdf', 37946, 0, NULL, NULL, '2026-06-26T13:18:41.646673+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('091a218d-8e85-4e84-96e6-bc48df2cb72e', 'Technologie de fabrication des pâtés charcutiers', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les étapes de fabrication des pâtés charcutiers, incluant les matières premières utilisées (gras de porc, foie, farine, condiments, etc.) et les procédés technologiques tels que le hachage, le pétrissage, le moulage et la cuisson. Il détaille les différentes phases de production, du mélange des ingrédients jusqu''au stockage réfrigéré du produit fini.', 'Techniques agroalimentaires', NULL, NULL, 'fr', NULL, '1782479932530-pates_charcutiers.pdf', 37567, 0, NULL, NULL, '2026-06-26T13:18:52.947579+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('8f2bdd70-0401-45ea-bfa4-c3795db6f519', 'Besoins de la plante et gestion du sol', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Document de formation de niveau 2 sur les besoins nutritionnels des plantes et la gestion de la fertilité des sols, destiné aux professionnels des cultures pérennes. Il couvre les éléments majeurs et oligo-éléments nécessaires à la nutrition des plantes, la fertilité du sol, et la méthodologie d''élaboration d''un plan de fumure.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782479939805-Perfectionnement_2_SM_2_-_Besoins_de_la_plante_et_gestion_du_sol.pdf', 7533476, 0, NULL, NULL, '2026-06-26T13:19:08.012475+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('529d9682-8eea-4aa3-a2dd-be9818c34e69', 'Technologie clé de compétitivité dans l''activité PLATS CUISINES APPERTISES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les diagrammes de fabrication et les étapes technologiques de production de plats cuisinés appertisés à base de poissons, de viandes et de pâtes farcies. Il détaille les procédés de transformation incluant la décongélation, la cuisson, l''emboîtage, la stérilisation et les conditions de stockage spécifiques à chaque type de produit.', 'Technologies agroalimentaires', NULL, NULL, 'fr', NULL, '1782479966185-plats_cuisines_appertises_de_poissons_viande_pates_farcies.pdf', 40900, 1, NULL, NULL, '2026-06-26T13:19:26.564493+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('cf65b615-7b84-45fa-9f21-000437fdf860', 'Technologie clé de compétitivité dans l''activité poissons fumés et bâtonnets surgelés', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les diagrammes de fabrication de produits transformés à base de poisson (poissons fumés innovants et traditionnels, bâtonnets de poisson panés surgelés) et de poitrine de porc fumée. Il décrit les étapes clés des procédés : réception des matières premières, salage, saumurage, fumage (dont fumage ionisé), séchage, surgélation, conditionnement et stockage réfrigéré. Il s''agit d''un document technique réalisé à l''ISAA-MF en 2004 sur les technologies de compétitivité da', 'Transformation agroalimentaire', NULL, NULL, 'fr', NULL, '1782479990379-poissons_fumes_batonnets_surgeles.pdf', 48093, 1, NULL, NULL, '2026-06-26T13:19:50.782004+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('66508d9c-e564-4eed-8459-2f09c801ffff', 'Technologie clé de compétitivité dans l’activité POMMES DE TERRE TRANSFORMÉES', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés de transformation industrielle des pommes de terre en divers produits surgelés tels que les frites, les pommes dauphines, les pommes noisettes, les croquettes et les flocons de purée. Il détaille les étapes de fabrication, du déterrage et lavage jusqu''au conditionnement, en passant par le pelage, la cuisson, le formage et la surgélation.', 'Techniques agroalimentaires', NULL, NULL, 'fr', NULL, '1782479999996-pommes_de_terre_frites_flocons_de_puree_croquettes_dauphines.pdf', 19274, 1, NULL, NULL, '2026-06-26T13:20:00.443771+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('4f825190-ea31-4cc0-a7be-d6303ed08fd7', 'Technologie clé de compétitivité dans l''activité Poudres de lait', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document décrit le processus industriel de fabrication des poudres de lait, depuis la réception du lait cru jusqu''à l''ensachage du produit fini. Il détaille les étapes principales telles que l''écrémage, la pasteurisation, l''homogénéisation, l''évaporation et le séchage, ainsi que les différents usages finaux (alimentation humaine engraissée, alimentation animale). Il met en avant les paramètres techniques et les procédés d''instantanéisation et de standardisation.', 'Transformation laitière', NULL, NULL, 'fr', NULL, '1782480008940-poudre_de_lait.pdf', 50336, 2, NULL, NULL, '2026-06-26T13:20:09.255033+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('c9aca716-6b1b-4074-a932-02be92db2d16', 'Préparation et transformation de fruits et légumes - Module GL G-044', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce module, version 1 datée du 12 janvier 2021, constitue un guide de référence sur les bonnes pratiques d''hygiène, les diagrammes de processus et les points de contrôle critiques (CCP) relatifs à la préparation et à la transformation des fruits et légumes. Il détaille le champ d''application, les modalités d''application et les points d''attention pour garantir la qualité et la sécurité des produits transformés.', 'Industrie agroalimentaire', NULL, NULL, 'fr', NULL, '1782480020403-Pr_paration_et_transformation_de_fruits_et_l_gumes_2021_v1.pdf', 6910349, 0, NULL, NULL, '2026-06-26T13:20:28.640738+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('ed4409f0-9ec1-4ad0-abe9-30dae8f1481b', 'Mieux produire la tomate en toute période au Bénin', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document, publié en août 2019 par l''Institut National des Recherches Agricoles du Bénin (INRAB) avec l''appui du Projet d''Appui au Développement du Maraîchage (PDMAR), est un guide de production de la tomate au Bénin.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782480035135-RTE-Tomate-definitif-4.pdf', 21310236, 0, NULL, NULL, '2026-06-26T13:20:56.548146+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('482ea243-3b49-41c3-a28f-6e130c880f33', 'ISAA - MF 2005 : Technologie clé de compétitivité dans l''activité Sucre Brut & Sucre Roux', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés industriels de production de sucre brut de betterave et de sucre roux de canne, détaillant les étapes clés telles que la réception des matières premières, la diffusion, la carbonatation, l''évaporation, la cuisson sous vide, le turbinage et le conditionnement. Il met en évidence les technologies visant à améliorer la compétitivité dans l''activité sucrière. Il couvre les flux debetteraves et de cannes à sucre à travers les différentes opérations de trans', 'Agro-industrie sucrière', NULL, NULL, 'fr', NULL, '1782480064385-sucre_de_betterave_roux_de_canne_melasse.pdf', 47366, 1, NULL, NULL, '2026-06-26T13:21:04.790038+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('b56fa2a2-6158-4093-b1c2-05d90a573fd1', 'Technologie clé de compétitivité dans l''activité SUCRE RAFFINE', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les différents procédés industriels de fabrication du sucre raffiné, en détaillant les étapes de transformation du sucre brut et du sucre roux de canne de betterave. Il illustre à travers un schéma processus les techniques de purification, de cristallisation et de conditionnement du sucre.', 'Agroalimentaire / Industrie sucrière', NULL, NULL, 'fr', NULL, '1782480070919-sucre_raffine_sucre_glace.pdf', 42689, 0, NULL, NULL, '2026-06-26T13:21:11.35855+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('cd1cc3f6-cc46-4075-a8ff-9d277e4e1670', 'Technologie clé de compétitivité dans l''activité Cacao – Chocolat (ISAA-MF 2004)', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Ce document présente les procédés industriels de transformation des fèves de cacao en produits finis tels que le chocolat, le beurre de cacao et la poudre de cacao. Il détaille les étapes clés de la chaîne de production, de la réception des fèves jusqu''au conditionnement, en passant par la fermentation, la torréfaction, le pressage et le conchage. Il met en évidence les technologies critiques qui déterminent la compétitivité dans l''industrie cacao-chocolat.', 'Technologies de transformation agroalimentaire', NULL, NULL, 'fr', NULL, '1782480079577-tablettes_chocolat_beurre_cacao.pdf', 35889, 0, NULL, NULL, '2026-06-26T13:21:19.978634+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('aa80529e-bb9b-4c39-ac59-4a316c276446', 'Fiche technique : La tomate - Solanum lycopersicum L.', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Fiche technique éditée par la Direction de l''agriculture de Polynésie française en 2018, présentant la culture de la tomate (Solanum lycopersicum L.) en climat tropical. Elle détaille le cycle de la plante, les conditions thermiques optimales, le choix variétal adapté au climat polynésien et aux maladies présentes (notamment le virus TYLC), ainsi que les méthodes de semis en pépinière.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782480084164-tomate-ft-culture_SDRdag_v2016.pdf', 2066216, 2, NULL, NULL, '2026-06-26T13:21:26.552068+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('e207d17c-c9f9-4c4b-9678-fd330c8977cb', 'Fiche technique sur la tomate', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Cette fiche technique présente les exigences pédoclimatiques de la tomate au Maroc, notamment en matière de température, de sol, de pH et de salinité. Elle décrit également les critères de choix du matériel végétal et les caractéristiques de variétés commerciales telles que Zayda RZ F1, Pristyla et Twarga, avec leurs résistances aux maladies.', 'Techniques agricoles', NULL, NULL, 'fr', NULL, '1782480093394-tomate.pdf', 1220571, 0, NULL, NULL, '2026-06-26T13:21:34.764231+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('7e92701c-017e-45cc-9649-1730fcbe4499', 'Technologie clé de compétitivité dans l''activité VIANDES DE BOUCHERIE', 'Auteur inconnu', 'fiche_technique', 'public', 'publie', 'Document technique décrivant les étapes et les processus de la filière viande de boucherie, depuis la réception des animaux jusqu''à la transformation des viandes et sous-produits.', 'Transformation des viandes', NULL, NULL, 'fr', NULL, '1782480100618-viandes_de_boucherie_farines_animales_noir_animal_abats.pdf', 17480, 3, NULL, NULL, '2026-06-26T13:21:40.827785+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('e6abfc9c-acd1-4d77-946f-04a8c1026a59', 'Comment travailler dans l''économie verte ? Guide destiné aux jeunes, aux chercheurs d''emploi et à ceux qui les accompagnent', 'Auteur inconnu', 'guide_pratique', 'public', 'publie', 'Ce guide, publié par l''Organisation internationale du Travail en 2022, s''adresse aux jeunes, aux chercheurs d''emploi et à leurs accompagnateurs. Il fournit des conseils pratiques pour s''orienter et travailler dans le secteur de l''économie verte. Il fait partie de la collection « Construire mon avenir au travail ».', 'Emploi et économie verte', NULL, NULL, 'fr', NULL, '1782480116888-wcms_854023.pdf', 2960862, 3, NULL, NULL, '2026-06-26T13:22:01.11213+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('bcebd16d-3c7b-4a84-a03b-9eff9cc1a362', 'Essai d''analyse des tâches de l''agronome', 'Auteur inconnu', 'article', 'public', 'publie', 'Michel Sebillotte, maître de conférences à l''Institut National Agronomique de Paris-Grignon, propose une réflexion approfondie sur la discipline de l''agronomie, ses définitions, son histoire et ses relations avec l''agriculture. L''auteur examine les objectifs de travail de l''agronome, qu''il s''agisse de contribuer au développement théorique de l''agronomie ou d''agir au niveau de la pratique agricole, en s''appuyant sur son expérience au sein de l''INAPG et de diverses collaborations interna', 'Agronomie', NULL, NULL, 'fr', NULL, '1782480130800-_Agronomie_et_agriculture__essai_d_analyse_des_t_ches_de_l_agronome__2_.pdf', 2735614, 4, NULL, NULL, '2026-06-26T13:22:18.379478+00:00', NULL);
INSERT OR IGNORE INTO "documents" ("id", "titre", "auteurs", "type_doc", "acces", "statut", "resume", "thematique", "pays", "filiere", "langue", "annee", "fichier_r2_key", "taille_octets", "nb_telechargements", "depose_par", "valide_par", "created_at", "published_at") VALUES ('49192cf8-6241-4e56-b93f-61830c786844', 'Manuel de transformation du manioc (IITA)', 'IITA', 'guide_pratique', 'public', 'publie', 'Le manioc offre bien plus de débouchés que la vente en frais ; sa transformation locale ouvre au moins sept voies d''activité. Consultez ce manuel de transformation élaboré par l''Institut International d''Agriculture Tropicale (IITA).', 'Agroécologie', NULL, NULL, 'fr', 2024, 'seed/1785318871573-manuel_transformation_manioc.pdf', 995085, 5, NULL, NULL, '2026-07-29T09:54:35.866911+00:00', NULL);

